

# This file was *autogenerated* from the file check_01_three_routes.sage
from sage.all_cmdline import *   # import sage library

_sage_const_111 = Integer(111); _sage_const_60 = Integer(60); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_1j = ComplexNumber(0, '1'); _sage_const_1p1 = RealNumber('1.1')# <matrix_exp_conjugation>: exp(X) Y exp(-X) = sum (1/m!) ad_X^m(Y) = exp(ad_X)(Y)
# 3 経路を独立に計算して突き合わせる。
#   経路A: 行列指数による共役 exp(X) Y exp(-X)
#   経路B: m 重交換子の級数
#   経路C: ad_X を n^2 x n^2 の線型写像として行列表示し、その指数を Y に作用
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in dir() else "."
load(os.path.join(_dir, "../../_shared/operators.sage"))
import numpy as np
import math
rng = np.random.default_rng(int(_sage_const_111 ))
rep = CheckReport("matrix_exp_conjugation: 3 経路の一致")
NT = _sage_const_60 
for n in [_sage_const_1 ,_sage_const_2 ,_sage_const_3 ,_sage_const_4 ]:
    for trial in range(_sage_const_4 ):
        X = rng.normal(size=(n,n)) + _sage_const_1j *rng.normal(size=(n,n))
        X = X/np.sqrt(np.sum(np.abs(X)**_sage_const_2 ))*_sage_const_1p1 
        Y = rng.normal(size=(n,n)) + _sage_const_1j *rng.normal(size=(n,n))
        # A
        eX = _expm(X)
        A_ = eX @ Y @ _expm(-X)
        # B
        B_ = np.zeros((n,n), dtype=complex); t = Y.copy()
        for m in range(NT+_sage_const_1 ):
            B_ = B_ + t/math.factorial(m); t = comm(X, t)
        # C: vec(ad_X(Y)) = (X ⊗ I - I ⊗ X^T) vec(Y)（行優先 vec）
        L = np.kron(X, np.eye(n)) - np.kron(np.eye(n), X.T)
        C_ = (_expm(L) @ Y.reshape(-_sage_const_1 )).reshape(n,n)
        rep.close(A_, B_, f"n={n} t={trial}: 共役 = 級数")
        rep.close(A_, C_, f"n={n} t={trial}: 共役 = exp(ad_X)(Y)")
        rep.close(B_, C_, f"n={n} t={trial}: 級数 = exp(ad_X)(Y)")
        # (3) exp(X)^{-1} = exp(-X)
        rep.close(np.linalg.inv(eX), _expm(-X), f"n={n} t={trial}: exp(X)^-1 = exp(-X)")
        rep.close(eX @ _expm(-X), np.eye(n), f"n={n} t={trial}: exp(X)exp(-X) = I")
rep.finish()

